// Flatten whatever shape arrives into keys the CRM understands.
// Handles Zapier's flat output, LinkedIn's formResponse.answers array,
// and plain JSON. The CRM is forgiving about field names, so this is
// mostly about pulling nested answers up to the top level.

const body = $json.body ?? $json;
const out = { ...body };

// LinkedIn Lead Sync shape: formResponse.answers[{questionText, answer}]
const answers = body?.formResponse?.answers ?? body?.answers;
if (Array.isArray(answers)) {
  for (const a of answers) {
    const key = a?.questionText ?? a?.name ?? a?.key;
    const val = a?.answer ?? a?.value ?? (Array.isArray(a?.values) ? a.values[0] : undefined);
    if (key && val !== undefined && val !== null) out[String(key)] = val;
  }
}

// Build a full name if only first/last arrived.
if (!out.contact_name && !out.full_name) {
  const first = out.firstName ?? out.first_name ?? '';
  const last = out.lastName ?? out.last_name ?? '';
  const joined = `${first} ${last}`.trim();
  if (joined) out.contact_name = joined;
}

out.lead_source = out.lead_source ?? 'LinkedIn';

return { json: out };
